func TestMaximum(t *testing.T) {
	t.Run("caps exponential backoff at the maximum", func(t *testing.T) {
		s := New(Exponential(time.Second), Maximum(3*time.Second))
		expected := []time.Duration{1 * time.Second, 2 * time.Second, 3 * time.Second, 3 * time.Second, 3 * time.Second}
		for i := 0; i < 5; i++ {
			require.Equal(t, expected[i], s.Backoff(int64(i)))
		}
	})

	t.Run("passes through values below the maximum", func(t *testing.T) {
		s := New(Exponential(time.Second), Maximum(10*time.Second))
		expected := []time.Duration{1 * time.Second, 2 * time.Second, 4 * time.Second}
		for i := 0; i < 3; i++ {
			require.Equal(t, expected[i], s.Backoff(int64(i)))
		}
	})

	t.Run("caps constant strategy at the maximum", func(t *testing.T) {
		s := New(Constant(5*time.Second), Maximum(2*time.Second))
		expected := []time.Duration{2 * time.Second, 2 * time.Second, 2 * time.Second}
		for i := 0; i < 3; i++ {
			require.Equal(t, expected[i], s.Backoff(int64(i)))
		}
	})

	t.Run("passes constant strategy through when below maximum", func(t *testing.T) {
		s := New(Constant(1*time.Second), Maximum(5*time.Second))
		expected := []time.Duration{1 * time.Second, 1 * time.Second, 1 * time.Second}
		for i := 0; i < 3; i++ {
			require.Equal(t, expected[i], s.Backoff(int64(i)))
		}
	})

	t.Run("caps explicit strategy values above the maximum", func(t *testing.T) {
		s := New(Explicit(1*time.Second, 4*time.Second, 2*time.Second, 6*time.Second), Maximum(3*time.Second))
		expected := []time.Duration{1 * time.Second, 3 * time.Second, 2 * time.Second, 3 * time.Second}
		for i := 0; i < 4; i++ {
			require.Equal(t, expected[i], s.Backoff(int64(i)))
		}
	})

	t.Run("zero maximum caps everything to zero", func(t *testing.T) {
		s := New(Exponential(time.Second), Maximum(0))
		expected := []time.Duration{0, 0, 0}
		for i := 0; i < 3; i++ {
			require.Equal(t, expected[i], s.Backoff(int64(i)))
		}
	})

	t.Run("maximum equal to a backoff value is returned as-is", func(t *testing.T) {
		require.Equal(t, 4*time.Second, New(Exponential(time.Second), Maximum(4*time.Second)).Backoff(2))
	})

	t.Run("maximum of MaxInt64 passes everything through", func(t *testing.T) {
		s := New(Exponential(time.Second), Maximum(time.Duration(math.MaxInt64)))
		expected := []time.Duration{1 * time.Second, 2 * time.Second, 4 * time.Second}
		for i := 0; i < 3; i++ {
			require.Equal(t, expected[i], s.Backoff(int64(i)))
		}
	})

	t.Run("caps multiple strategy at the maximum", func(t *testing.T) {
		s := New(Multiple(time.Second), Maximum(3*time.Second))
		expected := []time.Duration{0, 1 * time.Second, 2 * time.Second, 3 * time.Second, 3 * time.Second}
		for i := 0; i < 5; i++ {
			require.Equal(t, expected[i], s.Backoff(int64(i)))
		}
	})

	t.Run("caps overflow to the maximum instead of MaxInt64", func(t *testing.T) {
		require.Equal(t, 10*time.Second, New(Exponential(time.Second), Maximum(10*time.Second)).Backoff(40))
	})
}
